const fs = require("fs");
const vm = require("vm");

class ClassList {
  constructor() { this.values = new Set(); }
  toggle(name, enabled) { enabled ? this.values.add(name) : this.values.delete(name); }
  contains(name) { return this.values.has(name); }
}

function element(id) {
  return {
    id,
    textContent: "",
    hidden: true,
    style: {},
    attributes: {},
    classList: new ClassList(),
    parentElement: { setAttribute(name, value) { this[name] = value; } },
    setAttribute(name, value) { this.attributes[name] = value; },
  };
}

const ids = ["shells", "tide", "tide-status", "tide-bar", "result", "hud"];
const elements = Object.fromEntries(ids.map((id) => [id, element(id)]));
const context = {
  console,
  Math,
  clearInterval() {},
  performance: { now: () => 0 },
  requestAnimationFrame() {},
  window: { addEventListener() {} },
  document: {
    getElementById(id) {
      if (id === "game") {
        return { width: 480, height: 320, getContext: () => ({
          clearRect() {}, fillRect() {}, beginPath() {}, arc() {}, fill() {},
        }) };
      }
      return elements[id];
    },
  },
};
vm.createContext(context);
vm.runInContext(fs.readFileSync(process.argv[2], "utf8"), context);

function state(label) {
  const internal = vm.runInContext("({ remainingSeconds, roundState, shellCount, shells: shells.length })", context);
  console.log(`${label} remaining=${internal.remainingSeconds} state=${internal.roundState} tide=${elements.tide.textContent} urgent=${elements.hud.classList.contains("urgent")} aria=${elements["tide-bar"].parentElement["aria-valuenow"]} result=${JSON.stringify(elements.result.textContent)}`);
  return internal;
}

const initial = state("initial");
vm.runInContext("update(0.05)", context);
const decremented = state("after_50ms");
vm.runInContext("for (let i = 0; i < 799; i += 1) update(0.05)", context);
const boundary = state("nominal_10s");
vm.runInContext("for (let i = 0; i < 200; i += 1) update(0.05)", context);
const settled = state("nominal_0s");
const before = elements.result.textContent;
vm.runInContext("settleRound(); settleRound(); update(0.05)", context);
const repeated = state("after_repeat");

const checks = {
  initializesAt50: initial.remainingSeconds === 50 && elements["tide-bar"].parentElement["aria-valuemax"] === undefined,
  decrements: decremented.remainingSeconds < initial.remainingSeconds,
  nominal10Urgent: elements.hud.classList.contains("urgent") || boundary.roundState === "playing",
  nominal10HudIs10: boundary.remainingSeconds > 9.999 && boundary.remainingSeconds < 10.001,
  settlesAtNominal0: settled.remainingSeconds === 0 && settled.roundState === "settled",
  settlementOnlyNoLoss: elements.result.textContent.includes("潮汐结算") && !/失败|输|判负/.test(elements.result.textContent),
  idempotent: repeated.roundState === "settled" && elements.result.textContent === before,
};
