checks.nominal10HudIs10 = boundary.remainingSeconds > 0 && boundary.remainingSeconds < 10.001;
console.log(`checks ${JSON.stringify(checks)}`);
if (Object.values(checks).some((ok) => !ok) || elements.tide.textContent !== "0") process.exitCode = 1;

